import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Creating Tables in AL","description":"","frontmatter":{},"headers":[],"relativePath":"tables-fields-and-business-data/creating-a-table.md","filePath":"tables-fields-and-business-data/creating-a-table.md"}`),a={name:`tables-fields-and-business-data/creating-a-table.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="creating-tables-in-al" tabindex="-1">Creating Tables in AL <a class="header-anchor" href="#creating-tables-in-al" aria-label="Permalink to “Creating Tables in AL”">​</a></h1><p>We&#39;ll learn these topics by building a small <strong>training course catalogue</strong> in Business Central. We&#39;ll start with a basic table, then examine its fields, object IDs, primary key, and properties. After that, we&#39;ll create a page to view the data.</p><p>The goal is to understand not just how to write the code, but why each part exists.</p><h2 id="creating-a-table" tabindex="-1">Creating a table <a class="header-anchor" href="#creating-a-table" aria-label="Permalink to “Creating a table”">​</a></h2><p>As we discussed, a table defines the structure of business data and stores its records.</p><p>Imagine we&#39;re building a training management application. We need to store information about the courses our organization offers.</p><p>Each course might have:</p><ul><li>A unique course code.</li><li>A course name.</li><li>A description.</li><li>A price.</li></ul><p>In AL, we define a table using the <code>table</code> object.</p><p>Create a new file in your AL project called <code>Course.Table.al</code> and add the following:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace LearningAl;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>table 50102 Course</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    Caption = &#39;Course&#39;;</span></span>
<span class="line"><span>    DataClassification = CustomerContent;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    fields</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        field(1; &quot;Course Code&quot;; Code[20])</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Caption = &#39;Course Code&#39;;</span></span>
<span class="line"><span>            DataClassification = CustomerContent;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        field(2; &quot;Course Name&quot;; Text[100])</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Caption = &#39;Course Name&#39;;</span></span>
<span class="line"><span>            DataClassification = CustomerContent;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        field(3; Description; Text[250])</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Caption = &#39;Description&#39;;</span></span>
<span class="line"><span>            DataClassification = CustomerContent;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        field(4; Price; Decimal)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Caption = &#39;Price&#39;;</span></span>
<span class="line"><span>            DataClassification = CustomerContent;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    keys</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        key(PK; &quot;Course Code&quot;)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Clustered = true;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Save the file. We&#39;ll break down the important parts before publishing it.</p><h2 id="defining-fields-and-field-data-types" tabindex="-1">Defining fields and field data types <a class="header-anchor" href="#defining-fields-and-field-data-types" aria-label="Permalink to “Defining fields and field data types”">​</a></h2><p>Look at this part of our table:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>field(1; &quot;Course Code&quot;; Code[20])</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    Caption = &#39;Course Code&#39;;</span></span>
<span class="line"><span>    DataClassification = CustomerContent;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Every field declaration has three essential components:</p><p><code>field(Field ID; Field Name; Data Type)</code></p><table tabindex="0"><thead><tr><th>Component</th><th>Example</th><th>Purpose</th></tr></thead><tbody><tr><td>Field ID</td><td><code>1</code></td><td>Identifies the field within the table</td></tr><tr><td>Field name</td><td><code>&quot;Course Code&quot;</code></td><td>Identifies the field in AL code</td></tr><tr><td>Data type</td><td><code>Code[20]</code></td><td>Defines what kind of value the field can hold</td></tr></tbody></table><h3 id="understanding-the-data-types" tabindex="-1">Understanding the data types <a class="header-anchor" href="#understanding-the-data-types" aria-label="Permalink to “Understanding the data types”">​</a></h3><p>Our table uses four fields with three different data types.</p><table tabindex="0"><thead><tr><th>Field</th><th>Data type</th><th>Why we chose it</th></tr></thead><tbody><tr><td><code>&quot;Course Code&quot;</code></td><td><code>Code[20]</code></td><td>Course codes are identifiers, such as <code>CS101</code>.</td></tr><tr><td><code>&quot;Course Name&quot;</code></td><td><code>Text[100]</code></td><td>Stores a course name of up to 100 characters.</td></tr><tr><td><code>Description</code></td><td><code>Text[250]</code></td><td>Stores a longer description of up to 250 characters.</td></tr><tr><td><code>Price</code></td><td><code>Decimal</code></td><td>Stores a numeric value that can include a fractional part.</td></tr></tbody></table><p>Here are some other data types you&#39;ll encounter frequently:</p><table tabindex="0"><thead><tr><th>Data type</th><th>Purpose</th><th>Example</th></tr></thead><tbody><tr><td><code>Integer</code></td><td>Whole numbers</td><td>Number of lessons</td></tr><tr><td><code>Boolean</code></td><td>True or false values</td><td>Whether a course is active</td></tr><tr><td><code>Date</code></td><td>Calendar dates</td><td>Course start date</td></tr><tr><td><code>DateTime</code></td><td>Date and time</td><td>When a course was created</td></tr><tr><td><code>Time</code></td><td>Time of day</td><td>Course start time</td></tr><tr><td><code>Enum</code></td><td>A predefined set of named values</td><td>Course status</td></tr><tr><td><code>Guid</code></td><td>A globally unique identifier</td><td>An identifier for a record or resource</td></tr></tbody></table><p><strong>A useful rule:</strong> Choose the data type based on what the value represents, not just what it looks like.</p><p>For example, <code>CS101</code> contains numbers, but it&#39;s an identifier, not a number you need to perform arithmetic on. That&#39;s why <code>Code[20]</code> is appropriate.</p><p>Likewise, <code>Price</code> uses <code>Decimal</code> rather than <code>Integer</code> because prices can include fractional amounts.</p><h2 id="object-ids-and-naming-conventions" tabindex="-1">Object IDs and naming conventions <a class="header-anchor" href="#object-ids-and-naming-conventions" aria-label="Permalink to “Object IDs and naming conventions”">​</a></h2><p>Look at our table declaration:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>table 50102 Course</span></span></code></pre></div><p>There are three important parts:</p><ul><li><code>table</code> tells AL that we&#39;re declaring a table object.</li><li><code>50102</code> is the object&#39;s ID.</li><li><code>Course</code> is the object&#39;s name.</li></ul><h3 id="what-are-object-ids" tabindex="-1">What are object IDs? <a class="header-anchor" href="#what-are-object-ids" aria-label="Permalink to “What are object IDs?”">​</a></h3><p>Business Central uses object IDs to identify application objects.</p><p>For example, our project currently has these objects:</p><table tabindex="0"><thead><tr><th>Object</th><th style="text-align:right;">ID</th></tr></thead><tbody><tr><td>Product table</td><td style="text-align:right;">50100</td></tr><tr><td>Product List page</td><td style="text-align:right;">50101</td></tr><tr><td>Course table</td><td style="text-align:right;">50102</td></tr></tbody></table><p>These IDs must comply with the permitted object ID range for your project and must not conflict with other objects in the applicable scope.</p><p>For this exercise, we&#39;re using IDs in the <code>50100</code> range, assuming that range is available in your environment.</p><h3 id="what-are-naming-conventions" tabindex="-1">What are naming conventions? <a class="header-anchor" href="#what-are-naming-conventions" aria-label="Permalink to “What are naming conventions?”">​</a></h3><p>Naming conventions are guidelines that help developers name objects consistently.</p><p>For example:</p><table tabindex="0"><thead><tr><th>Object</th><th>Example name</th></tr></thead><tbody><tr><td>Table</td><td><code>Course</code></td></tr><tr><td>List page</td><td><code>Course List</code></td></tr><tr><td>Card page</td><td><code>Course Card</code></td></tr><tr><td>Codeunit</td><td><code>Course Management</code></td></tr><tr><td>Enum</td><td><code>Course Status</code></td></tr></tbody></table><p>Notice that the names describe the objects&#39; purposes.</p><p>In AL, table and field names can contain spaces and punctuation when appropriately quoted. For example, <code>&quot;Course Code&quot;</code> is valid.</p><p><strong>Why does this matter?</strong></p><p>Consistent naming makes a project easier to navigate, understand, and maintain, especially when an extension contains dozens or hundreds of objects.</p><p>One additional convention: custom AL objects generally use IDs from the range assigned to your extension. In real projects, always check your team&#39;s ID allocation and naming standards rather than assuming a particular range is available.</p><h2 id="primary-keys" tabindex="-1">Primary keys <a class="header-anchor" href="#primary-keys" aria-label="Permalink to “Primary keys”">​</a></h2><p>Now look at the bottom of our table:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>keys</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    key(PK; &quot;Course Code&quot;)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        Clustered = true;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This defines the table&#39;s primary key.</p><p>A <strong>primary key uniquely identifies a record in a table</strong>.</p><p>Imagine our course table contains the following data:</p><table tabindex="0"><thead><tr><th>Course Code</th><th>Course Name</th><th style="text-align:right;">Price</th></tr></thead><tbody><tr><td>CS101</td><td>Introduction to Programming</td><td style="text-align:right;">1500</td></tr><tr><td>CS102</td><td>Database Fundamentals</td><td style="text-align:right;">2000</td></tr><tr><td>CS103</td><td>Web Development</td><td style="text-align:right;">2500</td></tr></tbody></table><p>Each course has a unique code.</p><p>If we attempted to create another record with course code <code>CS101</code>, it would violate the primary key&#39;s uniqueness requirement.</p><h3 id="breaking-down-the-key-declaration" tabindex="-1">Breaking down the key declaration <a class="header-anchor" href="#breaking-down-the-key-declaration" aria-label="Permalink to “Breaking down the key declaration”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>key(PK; &quot;Course Code&quot;)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    Clustered = true;</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li><code>key</code> declares a key on the table.</li><li><code>PK</code> is the name we assigned to the key. It&#39;s a common abbreviation for <em>primary key</em>.</li><li><code>&quot;Course Code&quot;</code> is the field used to identify each record.</li><li><code>Clustered = true</code> specifies that this key is clustered.</li></ul><p>The key name <code>PK</code> is a developer-chosen name; the important part is that the key identifies records according to the fields specified.</p><h3 id="can-a-primary-key-contain-multiple-fields" tabindex="-1">Can a primary key contain multiple fields? <a class="header-anchor" href="#can-a-primary-key-contain-multiple-fields" aria-label="Permalink to “Can a primary key contain multiple fields?”">​</a></h3><p>Yes. A primary key can consist of multiple fields.</p><p>For example, imagine a table storing course sessions. A course might have multiple sessions, so the course code alone wouldn&#39;t uniquely identify each session.</p><p>A composite key could use both <code>Course Code</code> and <code>Session Code</code> to identify each record.</p><p>For our current table, however, a single field is sufficient.</p><p><strong>Remember:</strong> A table&#39;s primary key is essential for uniquely identifying its records. Other keys can also be defined to support different access patterns.</p><hr><h2 id="field-properties" tabindex="-1">Field properties <a class="header-anchor" href="#field-properties" aria-label="Permalink to “Field properties”">​</a></h2><p>Fields can have properties that control their metadata, behavior, and how they&#39;re used.</p><p>We&#39;ve already used two:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>field(4; Price; Decimal)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    Caption = &#39;Price&#39;;</span></span>
<span class="line"><span>    DataClassification = CustomerContent;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Let&#39;s understand them.</p><h3 id="caption" tabindex="-1"><code>Caption</code> <a class="header-anchor" href="#caption" aria-label="Permalink to “Caption”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Caption = &#39;Price&#39;;</span></span></code></pre></div><p>The caption is the user-friendly label associated with the field.</p><p>A caption can be displayed in the Business Central interface instead of relying solely on the field&#39;s technical name.</p><p>For example, a field named <code>CourseName</code> could have the caption <code>Course Name</code>.</p><h3 id="dataclassification" tabindex="-1"><code>DataClassification</code> <a class="header-anchor" href="#dataclassification" aria-label="Permalink to “DataClassification”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DataClassification = CustomerContent;</span></span></code></pre></div><p>This property classifies the type of data stored in the field.</p><p><code>CustomerContent</code> is appropriate for information such as course descriptions and names entered or maintained by users.</p><p>Data classification supports data governance and privacy-related processes. <strong>It does not, by itself, secure or encrypt the data.</strong></p><p>More values:</p><table tabindex="0"><thead><tr><th>Value</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><code>CustomerContent</code></td><td>Business content supplied or maintained by the customer</td><td>Course descriptions</td></tr><tr><td><code>EndUserIdentifiableInformation</code></td><td>Information that directly identifies an end user</td><td>A person&#39;s name or email address</td></tr><tr><td><code>EndUserPseudonymousIdentifiers</code></td><td>Identifiers associated with an end user that are pseudonymous rather than directly identifying</td><td>A pseudonymous user identifier</td></tr><tr><td><code>AccountData</code></td><td>Information associated with an account</td><td>Account-related information</td></tr><tr><td><code>OrganizationIdentifiableInformation</code></td><td>Information that identifies an organization</td><td>An organization&#39;s identifying details</td></tr><tr><td><code>SystemMetadata</code></td><td>Technical information about the system</td><td>System-generated metadata</td></tr><tr><td><code>ToBeClassified</code></td><td>Data whose classification has not yet been determined</td><td>A field awaiting classification</td></tr></tbody></table><h3 id="other-useful-field-properties" tabindex="-1">Other useful field properties <a class="header-anchor" href="#other-useful-field-properties" aria-label="Permalink to “Other useful field properties”">​</a></h3><p>Here are a few additional properties you&#39;ll encounter as we progress:</p><table tabindex="0"><thead><tr><th>Property</th><th>Purpose</th></tr></thead><tbody><tr><td><code>Caption</code></td><td>Specifies the user-facing label.</td></tr><tr><td><code>DataClassification</code></td><td>Classifies the data stored in the field.</td></tr><tr><td><code>Editable</code></td><td>Controls whether the field can be edited in supported contexts.</td></tr><tr><td><code>NotBlank</code></td><td>Requires a nonblank value for a field when applicable.</td></tr><tr><td><code>InitValue</code></td><td>Specifies an initial value for the field.</td></tr><tr><td><code>MinValue</code></td><td>Specifies the minimum permitted value for applicable data types.</td></tr><tr><td><code>MaxValue</code></td><td>Specifies the maximum permitted value for applicable data types.</td></tr></tbody></table><p>We&#39;ll explore these when we need them. Some properties have specific limitations or behaviors depending on the field&#39;s data type and the operation being performed.</p><p>For example, setting a field&#39;s <code>Editable</code> property to <code>false</code> isn&#39;t the same as enforcing a business rule that prevents the underlying data from being changed. Field validation and table logic require separate consideration.</p><hr><h2 id="what-happens-when-we-publish-this-table" tabindex="-1">What happens when we publish this table? <a class="header-anchor" href="#what-happens-when-we-publish-this-table" aria-label="Permalink to “What happens when we publish this table?”">​</a></h2><p>At this point, we&#39;ve defined the table&#39;s structure, but we haven&#39;t created any course records.</p><p>After saving the file, publish your extension using your usual AL workflow.</p><p>If compilation succeeds, the table definition will be included in your extension. However, <strong>you won&#39;t automatically get a visible page for managing courses</strong>.</p><p>That&#39;s why our next practical step will be to create a List page connected to the <code>Course</code> table. We can then return to the table topics and see the effects of our changes directly in Business Central.</p><h3 id="official-documentation" tabindex="-1">Official documentation <a class="header-anchor" href="#official-documentation" aria-label="Permalink to “Official documentation”">​</a></h3><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-table-object" target="_blank" rel="noreferrer">Table object</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-table-keys" target="_blank" rel="noreferrer">Table keys</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/library" target="_blank" rel="noreferrer">AL data types</a></li></ul><h3 id="quick-knowledge-check" tabindex="-1">Quick knowledge check <a class="header-anchor" href="#quick-knowledge-check" aria-label="Permalink to “Quick knowledge check”">​</a></h3><p>Before we move on, make sure you can answer these five questions:</p><ol><li>What is the difference between a table and a field?</li><li>Why would we use <code>Code[20]</code> for a course code rather than <code>Integer</code>?</li><li>What is the purpose of an object&#39;s ID?</li><li>Why did we choose <code>&quot;Course Code&quot;</code> as our primary key?</li><li>What is the difference between a field&#39;s <code>Caption</code> and its <code>DataClassification</code>?</li></ol><p>You don&#39;t need to memorize every property right now. The important thing is to understand how a table is structured and why we&#39;ve defined it this way.</p>`,100)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};